use semio_framework_job_context::testkit;
use super::*;
#[test]
fn real_child_source_closes_every_custody_stage_on_same_original_without_foreign_work(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let quantum=RetainedCloneGrant{maximum_items:1,..stock};let generation=Generation(row["generation"].as_u64().unwrap());
 let mut caller=semio_framework_job_testing_caller::OriginalJobFixtureCaller::admit(OperationId(row["operation"].as_u64().unwrap()),generation,stock,||Some(1),u64::MAX,s["fuel"].as_u64().unwrap());let mut foreign=semio_framework_job_testing_caller::OriginalJobFixtureCaller::admit(OperationId(row["foreignOperation"].as_u64().unwrap()),generation,stock,||Some(1),u64::MAX,s["fuel"].as_u64().unwrap());
 let mut child=caller.bare_turn(quantum,|cx|Ok(OriginalCallerChildSource::new(cx.original_source_parent()?,cx,OperationId(row["childOperation"].as_u64().unwrap()),generation)?)).unwrap();
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){if testkit::child_source_status(&child).0{break;}caller.bare_turn(quantum,|cx|{child.admit_step(cx.original_source_parent()?,cx)?;Ok(())}).unwrap();}assert!(testkit::child_source_status(&child).0);let identity=testkit::child_source_status(&child).2;let origin=testkit::child_source_status(&child).3;
 let units=caller.bare_turn(RetainedCloneGrant{maximum_items:0,..quantum},|cx|{let fuel=cx.fuel_remaining();let step=child.close_step(cx.original_source_parent()?,cx)?;assert_eq!(step.progress(),Default::default());Ok(fuel-cx.fuel_remaining())}).unwrap();assert_eq!(units,row["deniedWork"].as_u64().unwrap());assert!(!testkit::child_source_status(&child).1);assert!(testkit::child_source_status(&child).0);
 let mut work=Vec::new();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if child.terminal_is_empty(){break;}let result=foreign.bare_turn(quantum,|cx|child.close_step(cx.original_source_parent()?,cx));assert!(result.is_err());assert_eq!(foreign.receipt(),RetainedCloneProgress::default());assert_eq!(testkit::child_source_status(&child).2,identity);assert_eq!(testkit::child_source_status(&child).3,origin);
  let units=caller.bare_turn(quantum,|cx|{let fuel=cx.fuel_remaining();let step=child.close_step(cx.original_source_parent()?,cx)?;assert_eq!(step.progress().copied_bytes,0);Ok(fuel-cx.fuel_remaining())}).unwrap();work.push(units);
 }
 assert!(child.terminal_is_empty());assert_eq!(serde_json::to_value(work).unwrap(),row["work"]);let units=caller.bare_turn(quantum,|cx|{let fuel=cx.fuel_remaining();child.close_step(cx.original_source_parent()?,cx)?;Ok(fuel-cx.fuel_remaining())}).unwrap();assert_eq!(units,row["cachedWork"].as_u64().unwrap());drop(child);foreign.retire(stock);caller.retire(stock);
}

/// 🪙️ A real failed child-ledger birth reports independent CPU before propagating its original allocation cause.
#[test]
fn genuine_child_ledger_allocation_refusal_posts_actual_work_before_result(){
 use semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread;
 use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
 let law:serde_json::Value=serde_json::from_str(include_str!("constructor.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("constructor.schema.json")).unwrap();for(key,value)in law.as_object().unwrap(){assert_eq!(&schema["properties"][key]["const"],value)}
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..stock};let generation=Generation(row["generation"].as_u64().unwrap());let mut caller=semio_framework_job_testing_caller::OriginalJobFixtureCaller::admit(OperationId(row["operation"].as_u64().unwrap()),generation,stock,||Some(1),law["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut child=caller.bare_turn(q,|cx|Ok(OriginalCallerChildSource::new(cx.original_source_parent()?,cx,OperationId(row["childOperation"].as_u64().unwrap()),generation)?)).unwrap();let mut refused=false;
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){caller.bare_turn(q,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let((result,count),heap)=observe(||refuse_one_allocation_on_this_thread(||child.admit_step(cx.original_source_parent().unwrap(),cx)));assert!(!heap.overflowed);if count==0{result?;assert!(cx.original_work_units_spent()-work<=1)}else{assert_eq!(count,law["refusedAllocations"].as_u64().unwrap()as usize);let failure=result.unwrap_err();assert_eq!(failure.primary_value().unwrap().kind,semio_framework_value::ValueRefusalKind::AllocationFailed);assert_eq!(cx.original_work_units_spent()-work,u128::from(law["actualWork"].as_u64().unwrap()));assert_eq!(cx.retained_progress(),before);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!testkit::child_source_status(&child).0);refused=true;}Ok(())}).unwrap();if refused{break}}
 assert!(refused);for _ in 0..s["maximumTurns"].as_u64().unwrap(){if testkit::child_source_status(&child).0{break}caller.bare_turn(q,|cx|child.admit_step(cx.original_source_parent()?,cx)).unwrap();}assert!(testkit::child_source_status(&child).0);caller.cancel().cancel_now();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if child.terminal_is_empty(){break}caller.bare_turn(q,|cx|child.close_step(cx.original_source_parent()?,cx)).unwrap();}assert!(child.terminal_is_empty());drop(child);caller.retire(stock);
}
